#!/bin/sh
# Manifest of fixture HEAD, porcelain status and every file hash under .git (excluding objects) and .corvint.
cd "$1/fixture" && { echo "HEAD $(git rev-parse HEAD)"; git status --porcelain=v1 --untracked-files=all --ignored | sed 's/^/STATUS /'; find .git .corvint -type f -not -path '.git/objects/*' 2>/dev/null | LC_ALL=C sort | xargs shasum -a 256; }

